// HasDeployment applies the HasEdge predicate on the "deployment" edge.
func HasDeployment() predicate.DeploymentJob {
	return predicate.DeploymentJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DeploymentTable, DeploymentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDeploymentWith applies the HasEdge predicate on the "deployment" edge with a given conditions (other predicates).
func HasDeploymentWith(preds ...predicate.Deployment) predicate.DeploymentJob {
	return predicate.DeploymentJob(func(s *sql.Selector) {
		step := newDeploymentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DeploymentJob) predicate.DeploymentJob {
	return predicate.DeploymentJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DeploymentJob) predicate.DeploymentJob {
	return predicate.DeploymentJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DeploymentJob) predicate.DeploymentJob {
	return predicate.DeploymentJob(sql.NotPredicates(p))
}
